command:
// ==========================================
// LUNAS WIRKUNG: UNNATÜRLICHE SCHNELLIGKEIT (BRONA)
//
// - Ziel: Sich selbst (Wirkender)
// - Dauer: QS × 2 Kampfrunden
// - Geschwindigkeits-Bonus: +QS auf Geschwindigkeit (system.stats.gs.gearmodifier, Modus 2)
// - direkte Effektanlage über Block 6 & Wirkungsende über Block 7
// - keine GM-Anfrage nötig (auf sich selbst)
// ==========================================

(async function () {
    const macroUuid = this?.uuid || game.macros.getName("Unnatürliche Schnelligkeit")?.uuid || null;

    // +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++++++
    const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
    const frameworkFehlt =
        !globalThis.DSK?.Effekt?.Anwenden || !globalThis.DSK?.EffektEnde?.Register ||
        !globalThis.DSK?.QS?.Ermitteln || !globalThis.DSK?.Token?.Finde ||
        !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen;

    if (frameworkFehlt) {
        const fwMacro = await fromUuid(frameworkUuid);
        if (!fwMacro?.execute) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
        await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 150));
    }

    const DSK_FW = globalThis.DSK;
    if (
        !DSK_FW?.Effekt?.Anwenden || !DSK_FW?.EffektEnde?.Register ||
        !DSK_FW?.QS?.Ermitteln || !DSK_FW?.Token?.Finde ||
        !DSK_FW?.GabenUI?.AnfrageKarteErstellen
    ) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework 01.02 wurde nicht vollständig geladen!");

    // +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++++++
    const gabenName = "Unnatürliche Schnelligkeit", vollerName = "Unnatürliche Schnelligkeit (Brona)", ahne = "Brona";
    const endeKey = "bronaUnnatuerlicheSchnelligkeit";
    const endeText = "Die unnatürliche Schnelligkeit verblasst aus den Gliedmaßen. Die Bewegungsrate normalisiert sich wieder.";

    DSK_FW.EffektEnde.Register(endeKey, vollerName, endeText);

    // +++ 3 - HELFER ++++++++++++++++++++++++++++++++++++++++++++++
    const raeumeQSAuf = async actor => {
        if (actor?.getFlag("world", "letzteGabenQS") !== undefined) await actor.unsetFlag("world", "letzteGabenQS");
        if (actor?.getFlag("world", "letzteGabenMessageId") !== undefined) await actor.unsetFlag("world", "letzteGabenMessageId");
    };

    const findeEigeneEffekte = actor =>
        (actor?.effects || []).filter(e => (e.name || e.label || "") === vollerName);

    const beschreibungFuer = (casterName, qs, dauerRunden) =>
        `<b>${casterName}</b> entfesselt ihre unnatürliche Schnelligkeit!` +
        `<br><br>Die Bewegungen verschwimmen zu einem rasenden Schemen, während kurzfristig die Agilität enorm gesteigert wird.` +
        `<br>• <b>Bonus auf Geschwindigkeit (GS):</b> +${qs} (QS)` +
        `<br><br><b>Wirkungsdauer:</b> ${dauerRunden} Kampfrunden (${qs} QS × 2) | <b>Zielkategorie:</b> Sich selbst`;

    // +++ 4 - WIRKENDER +++++++++++++++++++++++++++++++++++++++++++
    let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character || null;

    if (!casterActor) {
        casterActor =
            canvas.tokens.placeables.map(token => token.actor).find(actor =>
                actor?.getFlag("world", "letzteGabenQS") !== undefined
            ) ||
            game.actors.find(actor =>
                actor.getFlag("world", "letzteGabenQS") !== undefined
            ) ||
            null;
    }

    if (!casterActor) {
        return ui.notifications.warn("Luna sagt 🌙: Kein Wirkender gefunden!");
    }

    if (!game.user.isGM && !casterActor.isOwner) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!"
        );
    }

    const casterToken = DSK_FW.Token.Finde(casterActor);
    if (!casterToken) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Der Wirkende braucht einen Token auf der aktuellen Szene!"
        );
    }

    const casterName = DSK_FW.ResolveTokenName(casterActor);

    // +++ 5 - QS ++++++++++++++++++++++++++++++++++++++++++++++++++
    const qs = DSK_FW.QS.Ermitteln({
        actor: casterActor,
        gabenName,
        suchbegriffe: ["Unnatürliche Schnelligkeit Probe", "Unnatürliche Schnelligkeit"],
        testDataObj: typeof testData !== "undefined" ? testData : null,
        fallback: 0,
        protokollieren: true
    });

    if (qs <= 0) {
        await DSK_FW.GabenUI.AnfrageKarteErstellen({
            gabenName: vollerName,
            ahne,
            beschreibung: "Die unnatürliche Schnelligkeit konnte nicht kanalisiert werden.",
            wirkender: casterName,
            ziele: [],
            misserfolge: [{ name: casterName }],
            dauerText: "Keine Wirkung",
            gmBereich: false,
            angewendet: true,
            erfolgreich: false,
            anfragenderUserId: game.user.id
        });

        await raeumeQSAuf(casterActor);
        return;
    }

    const dauerRunden = qs * 2;
    const dauerText = `${dauerRunden} Kampfrunden (${qs} QS × 2)`;
    const beschreibung = beschreibungFuer(casterName, qs, dauerRunden);

    // +++ 6 - ALTEN EIGENEN EFFEKT LÖSCHEN +++++++++++++++++++++++
    const alteEffekte = findeEigeneEffekte(casterActor);
    if (alteEffekte.length) {
        await casterActor.deleteEmbeddedDocuments("ActiveEffect", alteEffekte.map(e => e.id));
    }

    // +++ 7 - EFFEKT ANWENDEN +++++++++++++++++++++++++++++++++++++
    const direkteChanges = [
        { key: "system.stats.gs.gearmodifier", mode: 2, value: String(qs), priority: 20 }
    ];

    const erzeugterEffekt = await DSK_FW.Effekt.Anwenden({
        name: vollerName,
        ahne,
        beschreibung: `Erhöht kurzfristig die Geschwindigkeit (GS) um ${qs}.<br><br><b>Wirkungsdauer:</b> ${dauerText}`,
        gabeZiel: "",
        qs,
        ziel: casterActor,
        changes: direkteChanges,
        duration: { rounds: dauerRunden },
        showIcon: 1,
        flags: {
            dsk: {
                isUnnatuerlicheSchnelligkeit: true,
                casterUuid: casterActor.uuid,
                qs,
                wirkungsende: {
                    sfName: endeKey,
                    basisEffektName: vollerName,
                    beschreibungFuerEnde: endeText
                }
            }
        }
    });

    if (!erzeugterEffekt) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.error("Luna sagt 🌙: Der Effekt für Unnatürliche Schnelligkeit konnte nicht angelegt werden!");
    }

    // +++ 8 - KARTE ERSTELLEN +++++++++++++++++++++++++++++++++++++
    await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName,
        ahne,
        beschreibung,
        wirkender: casterName,
        ziele: [{ name: `${casterName} (+${qs} Geschwindigkeit)`, rolle: "Rasender Schemen" }],
        misserfolge: [],
        dauerText,
        gmBereich: false,
        angewendet: true,
        erfolgreich: true,
        anfragenderUserId: game.user.id
    });

    await raeumeQSAuf(casterActor);
}).call(this);
